export type ResolvedSettings = Record<string, string>;

export class ConfigurationCatalog {
  private readonly settings: Setting[];
  constructor(settings: readonly Setting[]) {
    const seen = new Set<string>();
    this.settings = settings.map(setting => {
      if (!setting.key.trim() || typeof setting.value !== 'string') throw new Error('Invalid setting');
      const identity = `${setting.scope}\0${setting.key}`;
      if (seen.has(identity)) throw new Error('Duplicate setting');
      seen.add(identity);
      return setting;
    });
  }
  resolve(): ResolvedSettings {
    const effective = new Map<string, string>();
    for (const setting of this.settings) {
      if (setting.scope === 'default') effective.set(setting.key, setting.value);
    }
    for (const setting of this.settings) {
      if (setting.scope === 'environment') effective.set(setting.key, setting.value);
    }
    const result: Record<string, string> = {};
    for (const key of [...effective.keys()].sort()) result[key] = effective.get(key)!;
    return result;
  }
  get(key: string): string | undefined {
    if (!key.trim()) throw new Error('Blank key');
    return this.resolve()[key];
  }
  withEnvironment(overrides: readonly Omit<Setting, 'scope'>[]): ConfigurationCatalog {
    const defaults = this.settings
      .filter(setting => setting.scope === 'default')
      .map(setting => ({ ...setting }));
    const environment = overrides.map(setting => ({
      key: setting.key,
      value: setting.value,
      scope: 'environment' as const
    }));
    return new ConfigurationCatalog([...defaults, ...environment]);
  }
}

