import { ConfigurationCatalog, Setting } from './solution';

function equal(actual: unknown, expected: unknown, message: string): void { if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`); }
function deepEqual(actual: unknown, expected: unknown, message: string): void { if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(`${message}: ${JSON.stringify(actual)}`); }
function throws(action: () => unknown, message: string): void { let didThrow = false; try { action(); } catch { didThrow = true; } if (!didThrow) throw new Error(message); }

const input: Setting[] = [
  { key: 'zeta', value: 'default-z', scope: 'default' },
  { key: 'alpha', value: 'default-a', scope: 'default' },
  { key: 'zeta', value: 'environment-z', scope: 'environment' }
];
const catalog = new ConfigurationCatalog(input);
input[0].value = 'mutated';
input.push({ key: 'extra', value: 'bad', scope: 'default' });
deepEqual(catalog.resolve(), { alpha: 'default-a', zeta: 'environment-z' }, 'environment overrides and constructor input is copied');
deepEqual(Object.keys(catalog.resolve()), ['alpha', 'zeta'], 'resolved keys sorted');
equal(catalog.get('zeta'), 'environment-z', 'get returns effective environment value');
equal(catalog.get('missing'), undefined, 'missing get returns undefined');
throws(() => catalog.get('   '), 'blank lookup rejected');

const resolved = catalog.resolve();
resolved.alpha = 'corrupt';
resolved.added = 'corrupt';
deepEqual(catalog.resolve(), { alpha: 'default-a', zeta: 'environment-z' }, 'resolve returns independent object');

const overrides: Setting[] = [
  { key: 'alpha', value: 'environment-a', scope: 'environment' },
  { key: 'newKey', value: 'new-value', scope: 'environment' }
];
const replaced = catalog.withEnvironment(overrides);
overrides[0].value = 'mutated';
overrides.pop();
deepEqual(replaced.resolve(), { alpha: 'environment-a', newKey: 'new-value', zeta: 'default-z' }, 'environment scope replaced and overrides copied');
deepEqual(catalog.resolve(), { alpha: 'default-a', zeta: 'environment-z' }, 'original catalog remains independent');
const defaultsOnly = catalog.withEnvironment([]);
deepEqual(defaultsOnly.resolve(), { alpha: 'default-a', zeta: 'default-z' }, 'empty override removes prior environment');

throws(() => new ConfigurationCatalog([{ key: ' ', value: 'x', scope: 'default' }]), 'blank key rejected');
throws(() => new ConfigurationCatalog([
  { key: 'same', value: 'a', scope: 'default' },
  { key: 'same', value: 'b', scope: 'default' }
]), 'duplicate default rejected');
throws(() => new ConfigurationCatalog([
  { key: 'same', value: 'a', scope: 'environment' },
  { key: 'same', value: 'b', scope: 'environment' }
]), 'duplicate environment rejected');
throws(() => new ConfigurationCatalog([{ key: 'x', value: 3 as unknown as string, scope: 'default' }]), 'non-string value rejected');
deepEqual(new ConfigurationCatalog([]).resolve(), {}, 'empty catalog valid');

